        '# -- verify probe --------------------------------------------------------------------\n\n\ndef test_verify_signed_out(tmp_path):\n    result = codex_auth.verify(SecretStore(tmp_path / "s.json"))\n    assert result["ok"] is False and result["state"] == "signed_out"\n\n\ndef test_verify_spends_no_plan_usage(tmp_path, monkeypatch):\n    """The Test button checks the credential, never the model.\n\n    The regression this pins: verify used to POST a 16-token completion to the\n    subscription backend, so pressing "Test" drew on the user\'s plan every time.\n    """\n    secrets = SecretStore(tmp_path / "s.json")\n    _seed(secrets)\n\n    def refuse(*args, **kwargs):  # any HTTP at all is a failure here\n        raise AssertionError("verify must not call the backend")\n\n    monkeypatch.setattr("httpx.post", refuse)\n    monkeypatch.setattr("httpx.get", refuse, raising=False)\n    result = codex_auth.verify(secrets)\n    assert result["ok"] is True\n    assert result["account"] == "user@example.com"\n    assert "no model call" in result["note"]\n\n\ndef test_verify_reports_a_dead_session_without_calling_the_model(tmp_path, monkeypatch):\n    secrets = SecretStore(tmp_path / "s.json")\n    # A stale bearer with a refresh token the endpoint rejects: signed out, and the\n    # rejection comes from the token endpoint, not from an inference call.\n    _seed(secrets, exp_offset=-10)\n    monkeypatch.setattr(\n        codex_auth, "_token_post", lambda data, timeout=30.0: _token_response(400, {})\n    )\n    monkeypatch.setattr(\n        "httpx.post", lambda *a, **k: (_ for _ in ()).throw(AssertionError("no inference"))\n    )\n    result = codex_auth.verify(secrets)\n    assert result["ok"] is False and result["state"] == "signed_out"\n\n\n# -- REST surface --------------------------------------------------------------------\n',
